using System.Collections.Generic;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "ViolentFlingAction", menuName = "Data/Battle/Battle Actions/Tactical Actions/ViolentFling Action")]
public class ViolentFlingAction : ChooseDiceAction
{
	[Header("Destroy Action")]
	[SerializeField]
	private PurifyAction purifyAction;

	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	[Header("Debug")]
	[HorizontalLine(2f, EColor.Gray)]
	[SerializeField]
	protected bool verbose;

	public override bool CheckConditionToBeCasted(bool playerHand, DiceOwnerEnum diceOwnerEnum)
	{
		return ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceInHandAmount() > 1;
	}

	public override void CastAmount(int amount, GameObject source)
	{
		for (int i = 0; i < diceList.Count; i++)
		{
			DiceInstance diceInstance = diceList[i];
			$"DESTROY HAND DICE: Destroyed dice {diceInstance.name}".DebugLogIfVerbose(verbose);
			ReferenceSingleton<PlayerDiceHandHolder>.Instance.RemoveDiceFromHand(diceInstance);
			diceInstance.StoreDiceInstance();
		}
		List<GameObject> activeCorruptedAnimals = currentCorruptedAnimals.activeCorruptedAnimals;
		purifyAction.CastTargetAmount(activeCorruptedAnimals.PickRandom(), amount, source);
		CastWithPossibleRandomPurifyAsSecondAction();
	}
}
